import React, { useCallback, useContext, useEffect, useMemo, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { GIFData } from './../../ricos-schema/next-schema/index.js';
import { GIFData_GIFType } from './../../ricos-schema/next-schema/index.js';
import { usePrefersReducedMotion } from './../../_shared/use-prefers-reduced-motion.js';
import { Image } from './../../ui-components/Components/image.js';

import { ROOT } from '../data-hooks.js';
import classes from './giphy-viewer-scss.js';
import { PlayIcon } from './play-icon.js';

type Props = {
  componentData: GIFData;
  nodeId: string;
};

export const Giphy: React.FC<Props> = ({ componentData, nodeId }) => {
  const { width, height, gifType } = componentData;
  const { original } = componentData;
  const { tabIndex } = useContext(RicosContext);
  const isEditor = tabIndex === -1;
  const videoRef = React.useRef<HTMLVideoElement>(null);
  const prefersReducedMotion = usePrefersReducedMotion();
  const [isPlaying, setIsPlaying] = useState(() => !prefersReducedMotion);

  useEffect(() => {
    if (isEditor) {
      return;
    }
    setIsPlaying(!prefersReducedMotion);
    const video = videoRef.current;
    if (video && video.readyState >= HTMLMediaElement.HAVE_FUTURE_DATA) {
      prefersReducedMotion && isPlaying ? video.pause() : video.play();
    }
  }, [prefersReducedMotion]);

  const handleTogglePlay = () => {
    const video = videoRef.current;
    if (video) {
      video.paused ? video.play() : video.pause();
    }
    setIsPlaying(prev => !prev);
  };

  const videoSrc = original?.mp4;

  if (videoSrc && gifType !== GIFData_GIFType.STICKER) {
    return (
      <InteractiveGifContainer isPlaying={isPlaying} onTogglePlay={handleTogglePlay}>
        <video
          ref={videoRef}
          autoPlay={!prefersReducedMotion || isEditor}
          muted
          loop
          playsInline // required for autoplay in iOS
          data-hook={getGifDatahook(isPlaying)}
          className={classes.giphy_player}
          src={videoSrc}
        />
      </InteractiveGifContainer>
    );
  }

  const animatedSrc = !isPlaying && original?.still ? original.still : original?.gif;

  const isInfoForWixImageReady =
    nodeId !== undefined && width !== undefined && height !== undefined && animatedSrc;

  if (isInfoForWixImageReady) {
    return (
      <InteractiveGifContainer isPlaying={isPlaying} onTogglePlay={handleTogglePlay}>
        <Image
          id={nodeId}
          containerId={`${nodeId}-parent`}
          aria-label="gif"
          height={height}
          width={width}
          containerProps={{
            className: classes.gifRatio,
            containerId: `${nodeId}-parent`,
            style: {
              '--dim-height': height,
              '--dim-width': width,
            } as React.CSSProperties,
            dataHook: getGifDatahook(isPlaying),
          }}
          displayMode="fill"
          className={classes.giphy_player}
          uri={animatedSrc}
          alt="gif"
        />
      </InteractiveGifContainer>
    );
  }

  return (
    <InteractiveGifContainer isPlaying={isPlaying} onTogglePlay={handleTogglePlay}>
      <img
        aria-label="gif"
        className={classes.giphy_player}
        src={animatedSrc}
        alt="gif"
        data-hook={getGifDatahook(isPlaying)}
      />
    </InteractiveGifContainer>
  );
};

const getGifDatahook = (isPlaying: boolean) => `${ROOT} ${isPlaying ? 'playing' : 'paused'}`;

const InteractiveGifContainer: React.FC<{
  isPlaying: boolean;
  onTogglePlay: () => void;
  children: React.ReactNode;
}> = ({ isPlaying, onTogglePlay, children }) => {
  const { tabIndex } = useContext(RicosContext);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (tabIndex === -1) {
        return;
      }

      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        onTogglePlay();
      }
    },
    [tabIndex, onTogglePlay]
  );

  const tabIndexProps = useMemo(() => {
    if (tabIndex === -1) {
      return {};
    }

    return {
      tabIndex,
      onClick: onTogglePlay,
      onKeyDown: handleKeyDown,
      ariaLabel: isPlaying ? 'Pause gif' : 'Play gif',
      role: 'button',
    };
  }, [tabIndex, onTogglePlay, handleKeyDown, isPlaying]);

  return (
    <div className={classes.giphyWrapper} {...tabIndexProps}>
      {children}
      {!isPlaying && (
        <span className={classes.playIcon}>
          <PlayIcon />
        </span>
      )}
    </div>
  );
};
