import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULT_CONFIGS } from './constants.js';
import type { GiphyPluginViewerConfig } from './types.js';
import { GIPHY_TYPE } from './types.js';
import { nodeViewRenderers } from './viewer/node-view-renderers.js';

export const pluginGiphy: ViewerPluginCreator<GiphyPluginViewerConfig> = config => {
  return {
    config: { ...DEFAULT_CONFIGS.viewer, ...config },
    type: GIPHY_TYPE,
    nodeViewRenderers,
  };
};
